db:insert.db:input-parameters:
#[{
  invoiceId: vars.invoiceId,
  sourceChannel: vars.request.sourceChannel,
  submittedBy: vars.request.submittedBy,
  correlationId: correlationId
}]

#[{
  invoiceId: vars.invoiceId,
  correlationId: correlationId,
  message: 'Document received via ' ++ vars.request.sourceChannel ++ ' (' ++ (vars.request.document.mimeType default '') ++ ', ' ++ ((vars.request.document.sizeBytes default 0) as String) ++ ' bytes)',
  actor: vars.request.submittedBy
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
fun view(rows) = rows map ((r) -> {
  invoiceId: r.invoice_id, invoiceNumber: r.invoice_number, status: r.status,
  totalAmount: r.total_amount, invoiceDate: r.invoice_date
})
---
{ exactMatches: view(vars.exact), possibleMatches: view(vars.possible) }
